# Extract cells by component bounding boxes + exact color; assign to the correct named piece.
out=[[0]*26 for _ in range(26)]
body_cells={}; marker_cells={}; collisions=[]
for name, p in pieces.items():
    color=p['color']; r0,r1,c0,c1=p['bbox']; dr,dc=p['offset']
    cells=[(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1) if G[r][c]==color]
    moved=[(r+dr,c+dc) for r,c in cells]
    body_cells[name]=moved
    for r,c in moved:
        if not (0<=r<26 and 0<=c<26): collisions.append(('oob body',name,r,c))
        elif out[r][c] not in (0,color): collisions.append(('body conflict',name,r,c,out[r][c]))
        out[r][c]=color
    mm=[(r+dr,c+dc) for r,c in p['marks']]
    marker_cells[name]=mm
    for r,c in mm:
        if not (0<=r<26 and 0<=c<26): collisions.append(('oob marker',name,r,c))
        elif out[r][c] not in (0,2): collisions.append(('marker/body conflict',name,r,c,out[r][c]))
        out[r][c]=2
